pub fn find_free_sectors(&self) -> Vec<(u64, u64)> {
    let mut free_sectors = Vec::new();
    let mut last_end = self.header.first_usable_lba;

    for (i, (_, partition)) in self.iter().enumerate() {
        let start = partition.starting_lba;
        if start > last_end {
            let size = start - last_end;
            let aligned_start = (last_end + self.align - 1) / self.align * self.align;
            let aligned_size = size / self.align * self.align;
            if aligned_size > 0 {
                free_sectors.push((aligned_start, aligned_size));
            }
        }
        last_end = partition.ending_lba + 1;
    }

    if last_end < self.header.last_usable_lba {
        let size = self.header.last_usable_lba + 1 - last_end;
        let aligned_start = (last_end + self.align - 1) / self.align * self.align;
        let aligned_size = size / self.align * self.align;
        if aligned_size > 0 {
            free_sectors.push((aligned_start, aligned_size));
        }
    }

    free_sectors
}

